class L{static calculateLayout(t,r,u,s,c,o=4){const n=t-u*2,i=r-u*2;let a=Math.floor((n+o)/(s+o)),e=Math.floor((i+o)/(c+o));return a<1&&(a=1),e<1&&(e=1),{id:`dynamic-${s}x${c}`,name:`Dynamic ${s}x${c}mm`,widthMm:s,heightMm:c,columns:a,rows:e}}static getPreset(t){return t==="barcode"?this.calculateLayout(210,297,5,64,25,4):this.calculateLayout(210,297,5,38,48,4)}static getLabelsPerPage(t){return t.columns*t.rows}}export{L};
